
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_sg4_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_sg4", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.318385261774141e+00, -4.236544494644350e+00, -4.121935491830937e+00, -3.963314706107028e+00, -3.747454667637643e+00, -3.460700258573362e+00, -3.092570699706985e+00, -2.641977082878392e+00, -2.124831227525160e+00, -1.578394560443935e+00, -1.060462213836698e+00, -7.081233058978642e-01, -6.037861298413681e-01, -5.025228445562416e-01, -3.671243761558209e-01, -2.350077628252591e-01, -1.338811695676534e-01, -5.033290252833183e-02, -1.082059226008027e-02, -1.216214763789553e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


